func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/sessions", wrapper.ListSessions)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/auth/sessions/{id}", wrapper.RevokeSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/pairing/token", wrapper.CreatePairingToken)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/pairing/consume", wrapper.ConsumePairingToken)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/events", wrapper.GetEvents)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/server/info", wrapper.GetServerInfo)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/server/setup/admin", wrapper.CreateAdmin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/assets", wrapper.UploadAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/timeline", wrapper.GetTimeline)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/assets/batch", wrapper.BatchAssets)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/favorites", wrapper.GetFavorites)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/hidden", wrapper.GetHidden)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/assets/{id}", wrapper.DeleteAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/{id}", wrapper.GetAsset)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/assets/{id}", wrapper.PatchAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/{id}/thumbnail", wrapper.GetAssetThumbnail)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/{id}/original", wrapper.GetAssetOriginal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/{id}/play", wrapper.PlayAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/assets/by-device-id/{deviceAssetId}", wrapper.GetAssetByDeviceId)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/trash", wrapper.GetTrash)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/trash/{id}/restore", wrapper.RestoreAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/people", wrapper.ListPeople)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/people/unnamed", wrapper.ListUnnamedPeople)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/people/{clusterId}", wrapper.GetPersonCluster)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/users", wrapper.ListUsers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/users", wrapper.CreateUser)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/admin/users/{id}", wrapper.UpdateUser)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/models/download", wrapper.DownloadModels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/models", wrapper.ListModels)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/admin/models/{id}", wrapper.ActivateModel)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/models/{id}/rerun", wrapper.RerunModel)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/models/scan", wrapper.ScanModels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/jobs", wrapper.ListJobs)
	})

	return r
}
